// To make a nice watercolor effect we have to implement realistic fluid simulation
// Here is the basic simulation based on Navier-Stokes equations using Jacobi iterations in Buffer B
// More Jacobi iterations = more accurate pressure solve = less divergence
// To make it as simple as possible let's pack all fluid properties to a single texels like this:
// texel.r - pigment color
// texel.g - pigment density
// texel.ba - fluid velocity

// We use these steps:
// 1. Buffer A - Advection - transporting fluid properties)
// 2. Buffer B - Viscous Diffusion - distribution the velocity areas of high velocity to areas of low velocity
// 3. Buffer C - Apply forces - let the fuild move
// 4. Buffer D - Relax divergence
// 5. Image - Use pigment color as red-blue channel and density as alpha

// Read more:
// https://developer.nvidia.com/gpugems/gpugems/part-vi-beyond-triangles/chapter-38-fast-fluid-dynamics-simulation-gpu
// https://jamie-wong.com/2016/08/05/webgl-fluid-simulation/
// https://grail.cs.washington.edu/projects/watercolor/paper_small.pdf

void mainImage( out vec4 fragColor, in vec2 fragCoord ) {
    vec4 pixel = texture(iChannel0,fragCoord / iResolution.xy);
    vec3 color = mix(vec3(0.9, 0.1, 0.1), vec3(0.1, 0.1, 0.9), pixel.r);
    float density = pixel.g;
    fragColor = vec4(mix(vec3(1.0), color, density), 1.0);
}

// Step 1: Advection
// ------------------------------------
// Advection: Transporting fluid properties (color, density, velocity) through the field as the fluid flows.
// This mimics the natural behavior of fluids by moving each property based on the velocity field.

vec4 drawCircle(vec4 fragColor, vec2 coord, vec2 center, float radius) {
    radius *= iResolution.x; // Scale radius based on screen resolution
    float alpha = smoothstep(radius + 10.0, radius - 10.0, length(coord - center * iResolution.xy));

    if (alpha == 0.0) {
        return fragColor;
    }

    alpha *= 1.0 - texture(iChannel3, coord / iChannelResolution[3].rg).g * CIRCLE_ROUGHNESS;
    float color = 1.0;//texture(iChannel3, coord / iChannelResolution[3].rg).r * 0.5;

    vec2 velocityForTheLeft = vec2(1.0, 0.0); // move right
    vec2 velocityForTheRight = vec2(-1.0, 0.0); // move left
    if (coord.x / iResolution.x < 0.5) {
        return vec4(1.0 - color, alpha, velocityForTheLeft.x, velocityForTheLeft.y); // moving right
    } else {
        return vec4(color, alpha, velocityForTheRight.x, velocityForTheRight.y); // moving left
    }
}

// Main function to handle frame rendering
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    if (iFrame == 0) {
        // Draw a circle on a transparent background on the first frame
        fragColor = vec4(0.0);
        fragColor = drawCircle(fragColor, fragCoord, vec2(0.35, 0.5), 0.09);
        fragColor = drawCircle(fragColor, fragCoord, vec2(0.65, 0.5), 0.09);
        // Or alternatively, load an image:
        // fragColor = vec4(texture(iChannel3, fragCoord / iResolution.xy).r, texture(iChannel3, fragCoord / iResolution.xy).g, 0.0, 0.0);
    } else if (iFrame % VISCOUS_DIFFUSION_ITERATIONS == 0) {
        // Sample the velocity at the current fragment's position
        vec2 velocityAtCoord = getVelocity(iChannel1, fragCoord, iResolution.xy);

        // Calculate the source coordinate by tracing backward along the velocity field
        vec2 sourceCoord = fragCoord - velocityAtCoord;

        // Sample the texture at the source coordinate using bilinear interpolation
        vec4 advectedProperties = sampleBilinear(iChannel1, sourceCoord, iResolution.xy);   

        // Output the advected properties (color, density, velocity)
        fragColor = advectedProperties;
    } else {
        fragColor = getAllProperties(iChannel1, fragCoord, iResolution.xy);
    }
}

// Step 2: Viscous Diffusion
// ------------------------------------
// Viscous diffusion describes how momentum spreads throughout a fluid due to its internal viscosity.
// Viscosity is the fluid's resistance to deformation or flow.
// This process redistributes velocity (momentum) from areas of high velocity to areas of low velocity,
// smoothing out sharp gradients and making the flow more uniform over time.
//
// Implementation:
// The simplest way to approximate viscous diffusion is by averaging neighboring texel velocities.
// This approach uses Jacobi Iteration, which is an iterative solver, and should be applied multiple times
// for accurate results.
//
// ALPHA: A weighting factor that balances the influence of the central texel against its neighbors.

#define ALPHA 1.0 // Central texel weighting factor

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Sample velocity from the current fragment and its neighbors
    vec2 velCenter = getVelocity(iChannel1, fragCoord, iResolution.xy);              // Central texel
    vec2 velLeft = getVelocity(iChannel1, fragCoord + vec2(-1.0, 0.0), iResolution.xy);  // Left neighbor
    vec2 velRight = getVelocity(iChannel1, fragCoord + vec2(1.0, 0.0), iResolution.xy);  // Right neighbor
    vec2 velTop = getVelocity(iChannel1, fragCoord + vec2(0.0, -1.0), iResolution.xy);  // Down neighbor
    vec2 velBottom = getVelocity(iChannel1, fragCoord + vec2(0.0, 1.0), iResolution.xy);     // Up neighbor

    // Compute the diffused velocity by averaging neighboring velocities with central texel weighting
    vec2 diffusedVelocity = (velCenter * ALPHA + velLeft + velRight + velTop + velBottom) / (4.0 + ALPHA);

    // Sample additional properties (color and density) at the current fragment position
    float color = getColor(iChannel1, fragCoord, iResolution.xy);  // Color property
    float density = getDensity(iChannel1, fragCoord, iResolution.xy); // Density property

    // Output the updated properties (color, density, and velocity)
    fragColor = clamp(vec4(color, density, diffusedVelocity.x, diffusedVelocity.y), -1.0, 1.0);
}

// Step 3: Apply Forces
// ------------------------------------
// In this step, forces like pressure and random perturbations are applied to the velocity field.
// This helps simulate realistic water dynamics, including movement driven by pressure gradients
// and randomness to introduce subtle natural variations.

vec2 generateRandomVelocity(vec2 fragmentCoord) {
    // Sample a random vector from the noise texture (iChannel3)
    // The range [-1.0, 1.0] is scaled by RANDOMNESS to control the strength of the perturbation
    return (texture(iChannel3, fragmentCoord / iResolution.xy).rg * 2.0 - 1.0) * RANDOMNESS;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Perform updates only every `VISCOUS_DIFFUSION_ITERATIONS` frames
    if (iFrame % VISCOUS_DIFFUSION_ITERATIONS == 0) {

        // Sample the current velocity, color, and density from the texture
        vec2 currentVelocity = getVelocity(iChannel1, fragCoord, iResolution.xy);
        float currentColor = getColor(iChannel1, fragCoord, iResolution.xy);
        float currentDensity = getDensity(iChannel1, fragCoord, iResolution.xy);

        // Sample neighboring densities to calculate the pressure gradient
        float densityLeft = getDensity(iChannel1, fragCoord + vec2(-1.0, 0.0), iResolution.xy);   // Left neighbor
        float densityRight = getDensity(iChannel1, fragCoord + vec2(1.0, 0.0), iResolution.xy);   // Right neighbor
        float densityTop = getDensity(iChannel1, fragCoord + vec2(0.0, -1.0), iResolution.xy);    // Top neighbor
        float densityBottom = getDensity(iChannel1, fragCoord + vec2(0.0, 1.0), iResolution.xy);  // Bottom neighbor

        // Calculate the water height gradient based on density differences
        vec2 pressureGradient = vec2(densityRight - densityLeft, densityBottom - densityTop) * 0.5;

        // Compute the water pressure force from the gradient
        vec2 pressureForce = -pressureGradient * PRESSURE_FACTOR;

        // Apply forces to the velocity field
        vec2 newVelocity = currentVelocity;
        newVelocity += pressureForce;                   // Apply pressure force
        newVelocity += generateRandomVelocity(fragCoord); // Apply random perturbation for natural variation

        // Clamp the velocity to prevent excessive flow
        newVelocity = clamp(newVelocity, -1.0, 1.0);

        // Perform a basic velocity diffusion step by averaging with neighboring velocities
        vec2 velocityLeft = getVelocity(iChannel1, fragCoord + vec2(-1.0, 0.0), iResolution.xy);   // Left neighbor
        vec2 velocityRight = getVelocity(iChannel1, fragCoord + vec2(1.0, 0.0), iResolution.xy);   // Right neighbor
        vec2 velocityTop = getVelocity(iChannel1, fragCoord + vec2(0.0, -1.0), iResolution.xy);    // Top neighbor
        vec2 velocityBottom = getVelocity(iChannel1, fragCoord + vec2(0.0, 1.0), iResolution.xy);  // Bottom neighbor

        // Viscous diffusion
        newVelocity = (newVelocity + velocityLeft + velocityRight + velocityTop + velocityBottom) / 5.0;

        // Write the updated fluid properties to the fragment output
        fragColor = vec4(currentColor, currentDensity, newVelocity.x, newVelocity.y);

    } else {
        // If no update is performed, output the current properties as-is
        fragColor = getAllProperties(iChannel1, fragCoord, iResolution.xy);
    }
}

#define VISCOUS_DIFFUSION_ITERATIONS 2
#define CIRCLE_ROUGHNESS 0.3
#define RANDOMNESS 0.3
#define PRESSURE_FACTOR 1.0
#define RELAX_DIVERGENCE_FACTOR 0.0

vec4 getAllProperties(sampler2D channel, vec2 coord, vec2 texSize) {
    return texture(channel, coord / texSize);
}

float getColor(sampler2D channel, vec2 coord, vec2 texSize) {
    return getAllProperties(channel, coord, texSize).r;
}

float getDensity(sampler2D channel, vec2 coord, vec2 texSize) {
    return getAllProperties(channel, coord, texSize).g;
}

vec2 getVelocity(sampler2D channel, vec2 coord, vec2 texSize) {
    return getAllProperties(channel, coord, texSize).ba;
}

vec4 sampleBilinear(sampler2D channel, vec2 coord, vec2 texSize) {
    // Calculate the fractional offset within the texel
    vec2 fractCoord = fract(coord - 0.5);

    // Calculate the integer base coordinates of the texel
    vec2 baseCoord = coord - fractCoord;

    // Fetch the four neighboring texels
    vec4 tex00 = texture(channel, (baseCoord + vec2(0.0, 0.0)) / texSize); // Top-left texel
    vec4 tex10 = texture(channel, (baseCoord + vec2(1.0, 0.0)) / texSize); // Top-right texel
    vec4 tex01 = texture(channel, (baseCoord + vec2(0.0, 1.0)) / texSize); // Bottom-left texel
    vec4 tex11 = texture(channel, (baseCoord + vec2(1.0, 1.0)) / texSize); // Bottom-right texel

    // Perform bilinear interpolation
    vec4 interpX0 = mix(tex00, tex10, fractCoord.x); // Interpolate along x-axis for row 0
    vec4 interpX1 = mix(tex01, tex11, fractCoord.x); // Interpolate along x-axis for row 1
    vec4 result = mix(interpX0, interpX1, fractCoord.y); // Interpolate along y-axis

    // Interpolate color on density-multiplicated values
    float colX0 = mix(tex00.r * tex00.g, tex10.r * tex10.g, fractCoord.x); // Interpolate along x-axis for row 0
    float colX1 = mix(tex01.r * tex01.g, tex11.r * tex11.g, fractCoord.x); // Interpolate along x-axis for row 1
    float col = mix(colX0, colX1, fractCoord.y) / result.g; // Demultiply
    result.r = col;

    return clamp(result, -1.0, 1.0);
}

// Step 4: Relax Divergence
// ------------------------------------
// This step adjusts the velocity field to reduce divergence, ensuring the fluid behaves more naturally.
// Divergence measures how much the velocity field "spreads out" or "compresses" at a point. 
// Relaxation smooths the velocity differences between neighbors.

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Sample current fluid properties
    vec2 currentVelocity = getVelocity(iChannel1, fragCoord, iResolution.xy); // Velocity at the current fragment
    float currentColor = getColor(iChannel1, fragCoord, iResolution.xy);      // Color (dye concentration)
    float currentDensity = getDensity(iChannel1, fragCoord, iResolution.xy);  // Fluid density

    // Velocity of neighboring texels
    vec2 velocityLeft, velocityRight, velocityDown, velocityUp;

    // Calculate divergence for the left neighbor
    velocityLeft = getVelocity(iChannel1, fragCoord + vec2(-2.0, 0.0), iResolution.xy);  // Two steps left
    velocityRight = getVelocity(iChannel1, fragCoord + vec2(0.0, 0.0), iResolution.xy);  // Current position
    velocityDown = getVelocity(iChannel1, fragCoord + vec2(-1.0, -1.0), iResolution.xy); // One left, one down
    velocityUp = getVelocity(iChannel1, fragCoord + vec2(-1.0, 1.0), iResolution.xy);    // One left, one up
    float divergenceLeft = (velocityLeft.x - velocityRight.x + velocityDown.y - velocityUp.y) * 0.5;

    // Calculate divergence for the right neighbor
    velocityLeft = getVelocity(iChannel1, fragCoord + vec2(0.0, 0.0), iResolution.xy);   // Current position
    velocityRight = getVelocity(iChannel1, fragCoord + vec2(2.0, 0.0), iResolution.xy);  // Two steps right
    velocityDown = getVelocity(iChannel1, fragCoord + vec2(1.0, -1.0), iResolution.xy);  // One right, one down
    velocityUp = getVelocity(iChannel1, fragCoord + vec2(1.0, 1.0), iResolution.xy);     // One right, one up
    float divergenceRight = (velocityLeft.x - velocityRight.x + velocityDown.y - velocityUp.y) * 0.5;

    // Calculate divergence for the top neighbor
    velocityLeft = getVelocity(iChannel1, fragCoord + vec2(-1.0, -1.0), iResolution.xy); // One left, one down
    velocityRight = getVelocity(iChannel1, fragCoord + vec2(1.0, -1.0), iResolution.xy); // One right, one down
    velocityDown = getVelocity(iChannel1, fragCoord + vec2(0.0, -2.0), iResolution.xy);  // Two steps down
    velocityUp = getVelocity(iChannel1, fragCoord + vec2(0.0, 0.0), iResolution.xy);     // Current position
    float divergenceTop = (velocityLeft.x - velocityRight.x + velocityDown.y - velocityUp.y) * 0.5;

    // Calculate divergence for the bottom neighbor
    velocityLeft = getVelocity(iChannel1, fragCoord + vec2(-1.0, 1.0), iResolution.xy);  // One left, one up
    velocityRight = getVelocity(iChannel1, fragCoord + vec2(1.0, 1.0), iResolution.xy);  // One right, one up
    velocityDown = getVelocity(iChannel1, fragCoord + vec2(0.0, 0.0), iResolution.xy);   // Current position
    velocityUp = getVelocity(iChannel1, fragCoord + vec2(0.0, 2.0), iResolution.xy);     // Two steps up
    float divergenceBottom = (velocityLeft.x - velocityRight.x + velocityDown.y - velocityUp.y) * 0.5;

    // Adjust the velocity to relax divergence
    vec2 divergenceGradient = vec2(divergenceRight - divergenceLeft, divergenceBottom - divergenceTop);
    currentVelocity -= divergenceGradient * 0.5 * RELAX_DIVERGENCE_FACTOR;

    // Clamp velocity to ensure stability
    currentVelocity = clamp(currentVelocity, -1.0, 1.0);

    // Output updated properties
    fragColor = vec4(currentColor, currentDensity, currentVelocity.x, currentVelocity.y);
}
